Q["a1-cases-accusative"] = {"version":1,"id":"a1-cases-accusative","topic":"a1-cases-accusative","level":"A1","title":"Stop: accusative","passScore":3,"items":[{"id":"a1-cases-accusative-q1","type":"multiple-choice","kind":"form","prompt":"Lubię ___. (I like music.)","options":["muzyka","muzykę","muzyką","muzyki"],"correct":1,"explanation":"Lubić takes the accusative. Feminine nouns change -a to -ę: muzykę.","optionNotes":["Nominative: the dictionary form, used for the subject.",null,"Instrumental (-ą), used after być and z.","Genitive, used after nie."]},{"id":"a1-cases-accusative-q2","type":"multiple-choice","kind":"form","prompt":"Mam ___. (I have a brother.)","options":["brat","bratem","bratę","brata"],"correct":3,"explanation":"Masculine nouns for people and animals take -a in the accusative: brata.","optionNotes":["Nominative. English does not change the noun here, Polish does.","Instrumental, as in Jestem bratem Anny.","-ę is the feminine ending.",null]},{"id":"a1-cases-accusative-q3","type":"multiple-choice","kind":"form","prompt":"Kupuję ___ telefon.","options":["nowy","nowego","nową","nowe"],"correct":0,"explanation":"Telefon is a masculine thing, so nothing changes: nowy telefon.","optionNotes":[null,"-ego is for masculine people and animals: nowego kolegę.","-ą is the feminine ending.","-e is the neuter ending."]},{"id":"a1-cases-accusative-q4","type":"multiple-choice","kind":"form","prompt":"Which sentence is correct?","options":["Piję dobra kawę.","Piję dobrą kawa.","Piję dobrą kawę.","Piję dobra kawa."],"correct":2,"explanation":"Both words change: the adjective takes -ą and the noun takes -ę.","optionNotes":["The adjective must change too.","The noun must change too.",null,"This is the nominative; the object needs the accusative."]}]};
Q["a1-functions-greetings-introductions"] = {"version":1,"id":"a1-functions-greetings-introductions","topic":"a1-functions-greetings-introductions","level":"A1","title":"Stop: greetings","passScore":3,"items":[{"id":"a1-functions-greetings-introductions-q1","type":"multiple-choice","kind":"function","prompt":"You walk into a small shop in the morning. What do you say?","options":["Cześć!","Dzień dobry!","Dobranoc!","Na razie!"],"correct":1,"explanation":"Dzień dobry is the formal hello for shops, offices and strangers.","optionNotes":["Cześć is only for friends and family.",null,"Dobranoc means good night, when you leave late or go to bed.","Na razie is an informal goodbye."]},{"id":"a1-functions-greetings-introductions-q2","type":"multiple-choice","kind":"function","prompt":"How do you ask a friend how they are?","options":["Jak się masz?","Jak się jesteś?","Jak się pan ma?","Jak masz?"],"correct":0,"explanation":"The informal question is Jak się masz? It uses masz (have), not jesteś (are).","optionNotes":[null,"A calque of English 'how are you'; Polish uses masz here.","This is formal, for a man you don't know well.","się is missing."]},{"id":"a1-functions-greetings-introductions-q3","type":"multiple-choice","kind":"form","prompt":"Mam ___ imię Ewa. (My name is Ewa.)","options":["na","moje","jest","się"],"correct":0,"explanation":"The fixed phrase is Mam na imię … (literally 'I have the name …').","optionNotes":[null,"A calque of 'my name'.","A calque of 'is'.","się belongs to Nazywam się …"]},{"id":"a1-functions-greetings-introductions-q4","type":"multiple-choice","kind":"function","prompt":"At noon you leave a meeting with a new client. What do you say?","options":["Cześć!","Na razie!","Do widzenia!","Dobranoc!"],"correct":2,"explanation":"Do widzenia is the formal goodbye.","optionNotes":["Cześć is informal: friends and family only.","Na razie is informal.",null,"Dobranoc is for late in the evening."]}]};
Q["a1-grammar-alphabet-pronunciation"] = {"version":1,"id":"a1-grammar-alphabet-pronunciation","topic":"a1-grammar-alphabet-pronunciation","level":"A1","title":"Stop: alphabet and stress","passScore":3,"items":[{"id":"a1-grammar-alphabet-pronunciation-q1","type":"multiple-choice","kind":"form","prompt":"Warszawa = war-sza-wa. Which syllable is stressed?","options":["war","sza","wa"],"correct":1,"explanation":"Polish stresses the second-to-last syllable: war-SZA-wa.","optionNotes":["English habit: stress on the first syllable.",null,"The last syllable is not stressed in Polish words like this."]},{"id":"a1-grammar-alphabet-pronunciation-q2","type":"multiple-choice","kind":"form","prompt":"Which spelling makes the same sound as ż?","options":["rz","sz","cz","z"],"correct":0,"explanation":"rz and ż are two spellings of one sound, like the s in pleasure.","optionNotes":[null,"sz is the sh in shop.","cz is the ch in church.","z is the z in zoo."]},{"id":"a1-grammar-alphabet-pronunciation-q3","type":"multiple-choice","kind":"form","prompt":"Which letter sounds like the w in English water?","options":["w","ł","u","l"],"correct":1,"explanation":"ł sounds like English w. Polish w sounds like v.","optionNotes":["Polish w sounds like v, as in van.",null,"u is a vowel, like the oo in book.","l is a clear l, as in leaf."]},{"id":"a1-grammar-alphabet-pronunciation-q4","type":"multiple-choice","kind":"form","prompt":"Which spelling is correct? (Thank you.)","options":["Dziekuje.","Dziękuje.","Dziekuję.","Dziękuję."],"correct":3,"explanation":"Both e's in dziękuję have the mark: dzię-ku-ję. The marks are part of the spelling.","optionNotes":["Both marks are missing.","The final ę is missing its mark.","The first ę is missing its mark.",null]}]};
Q["a1-grammar-pronouns-pan-pani"] = {"version":1,"id":"a1-grammar-pronouns-pan-pani","topic":"a1-grammar-pronouns-pan-pani","level":"A1","title":"Stop: pronouns and pan / pani","passScore":3,"items":[{"id":"a1-grammar-pronouns-pan-pani-q1","type":"multiple-choice","kind":"form","prompt":"Anna i Ewa? ___ są tu.","options":["Oni","One","Ono","Wy"],"correct":1,"explanation":"A group of women is one. Oni needs at least one man.","optionNotes":["Oni is for a group with at least one man.",null,"Ono is 'it', for neuter nouns.","Wy is 'you', not 'they'."]},{"id":"a1-grammar-pronouns-pan-pani-q2","type":"multiple-choice","kind":"function","prompt":"To an older man you don't know: How are you?","options":["Jak się masz?","Jak się pan ma?","Jak się pan masz?","Jak się macie?"],"correct":1,"explanation":"With strangers use pan (to a man) and the he form of the verb: ma.","optionNotes":["Informal: too familiar for a stranger.",null,"Pan takes the he form ma, not the you form masz.","Wy is never the polite form for one person."]},{"id":"a1-grammar-pronouns-pan-pani-q3","type":"multiple-choice","kind":"form","prompt":"Which pronoun replaces dziecko (a child)?","options":["on","ona","ono","one"],"correct":2,"explanation":"Dziecko is a neuter noun, so the pronoun is ono.","optionNotes":["On is for masculine nouns.","Ona is for feminine nouns.",null,"One is a plural pronoun."]},{"id":"a1-grammar-pronouns-pan-pani-q4","type":"multiple-choice","kind":"form","prompt":"Marek i Ola? ___ są tam.","options":["One","Oni","On","Ona"],"correct":1,"explanation":"The group has a man (Marek), so the pronoun is oni.","optionNotes":["One is only for groups with no men.",null,"On is one man; this is two people.","Ona is one woman; this is two people."]}]};
Q["a1-verbs-byc"] = {"version":1,"id":"a1-verbs-byc","topic":"a1-verbs-byc","level":"A1","title":"Stop: być","passScore":3,"items":[{"id":"a1-verbs-byc-q1","type":"multiple-choice","kind":"form","prompt":"My ___ tu. (We're here.)","options":["jesteśmy","jesteście","są","jest"],"correct":0,"explanation":"my → jesteśmy.","optionNotes":[null,"Jesteście goes with wy (you, plural).","Są goes with oni / one (they).","Jest is the he / she / it form."]},{"id":"a1-verbs-byc-q2","type":"multiple-choice","kind":"form","prompt":"Oni ___ tam. (They're over there.)","options":["jest","są","jesteście","jestem"],"correct":1,"explanation":"oni → są.","optionNotes":["Jest is singular: he / she / it is.",null,"Jesteście goes with wy.","Jestem is I am."]},{"id":"a1-verbs-byc-q3","type":"multiple-choice","kind":"form","prompt":"___ moje dzieci. (These are my children.)","options":["To jest","To są","Ten jest","To jesteś"],"correct":1,"explanation":"Dzieci is plural, so to są. To itself never changes.","optionNotes":["To jest is for one person or thing.",null,"Polish says to, not ten, when pointing: to jest, to są.","Jesteś is the you form."]},{"id":"a1-verbs-byc-q4","type":"multiple-choice","kind":"form","prompt":"Pani ___ bardzo miła. (You're very nice. – to a woman)","options":["jesteś","jest","jesteście","są"],"correct":1,"explanation":"Pani takes the she form of the verb: pani jest.","optionNotes":["Jesteś is the ty form; pani uses the she form.",null,"Wy is never the polite form for one person.","Są is plural."]}]};
